const express=require('express'),fs=require('fs'),path=require('path'),os=require('os'),crypto=require('crypto'),{spawn}=require('child_process');const{db}=require('../db'),{DATA_DIR}=require('../paths');const router=express.Router();const archive='/Applications/aPix Builder.app/Contents/Resources/app.asar',appId='2064644362323189762',templateId='monday-upscale-4k';let backend=null,starting=null,base=null;
