function settings(){const root=path.join(os.homedir(),'Library/Application Support/aPix Builder'),storage=path.join(root,'storage-settings.json');let config=path.join(root,'user','app-settings.json');if(fs.existsSync(storage)){const s=JSON.parse(fs.readFileSync(storage,'utf8'));if(s.configDir){const candidate=path.join(path.dirname(s.configDir),'app-settings.json');if(fs.existsSync(candidate))config=candidate}}const s=JSON.parse(fs.readFileSync(config,'utf8')).runningHub||{};const keys=(s.tokens||[]).filter(t=>t.enabled!==false&&t.apiKey).map(t=>t.apiKey);if(!keys.length&&s.apiKey)keys.push(s.apiKey);if(!keys.length)throw Error('Mở aPix một lần và lưu API key RunningHub.');return {apiKey:keys[0],apiKeys:keys,tokenPolicy:s.tokenPolicy||'priority',rotateIndex:s.rotateIndex||0}}
async function start(){if(base)return base;if(starting)return starting;starting=new Promise((resolve,reject)=>{if(!fs.existsSync(archive)){reject(Error('Không tìm thấy aPix Builder trong Applications.'));return}const dir=path.join(DATA_DIR,'apix-service');fs.mkdirSync(dir,{recursive:true});try{installTemplate(dir)}catch(e){reject(e);return}backend=spawn(process.execPath,[path.join(archive,'server/server.js')],{env:{...process.env,ELECTRON_RUN_AS_NODE:'1',APIX_DATA_ROOT:dir,APIX_RESOURCE_ROOT:archive,PORT:'0',APIX_SERVE_FRONTEND:'0'},stdio:['ignore','pipe','pipe']});let tail='',done=false;const timer=setTimeout(()=>{if(!done){done=true;backend.kill();reject(Error('Không khởi động được dịch vụ aPix.'))}},25000);backend.stdout.on('data',b=>{tail=(tail+b).slice(-3000);const m=tail.match(/listening on http:\/\/127\.0\.0\.1:(\d+)/);if(m&&!done){done=true;clearTimeout(timer);base='http://127.0.0.1:'+m[1];resolve(base)}});backend.stderr.on('data',()=>{});backend.on('error',()=>{clearTimeout(timer);if(!done){done=true;reject(Error('Không mở được backend aPix.'))}});backend.on('exit',()=>{base=null;starting=null;if(!done){done=true;clearTimeout(timer);reject(Error('Dịch vụ aPix dừng trước khi sẵn sàng.'))}})});try{return await starting}finally{starting=null}}
async function call(url,body){const r=await fetch((await start())+url,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15*60*1000)});const d=await r.json();if(!r.ok)throw Error(d.error||'aPix không xử lý được yêu cầu.');return d}
router.use((req,res,next)=>{if(!['127.0.0.1','::1','::ffff:127.0.0.1'].includes(req.socket.remoteAddress))return res.status(403).json({error:'Chỉ dùng trên máy này'});const origin=req.get('origin');if(origin&&!['http://localhost:'+req.socket.localPort,'http://127.0.0.1:'+req.socket.localPort].includes(origin))return res.status(403).json({error:'Nguồn yêu cầu không hợp lệ'});next()});
